INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2284605, 315726, 36403, '<td valign="top">The reflections in this are a little distracting.</td>', 'The reflections in this are a little distracting.', '2006-04-03 19:14:02.000000', NULL, 1),
(2284606, 315645, 36403, '<td valign="top">Cute.</td>', 'Cute.', '2006-04-03 19:14:25.000000', NULL, 1),
(2284607, 315013, 36403, '<td valign="top">Colors are a bit dull on this one.  Nice DOF choice.</td>', 'Colors are a bit dull on this one.  Nice DOF choice.', '2006-04-03 19:15:20.000000', NULL, 1),
(2284608, 315614, 36403, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2006-04-03 19:16:19.000000', NULL, 1),
(2284609, 315804, 36403, '<td valign="top">You couldn''t find a "brighter" banana?  =)</td>', 'You couldn''t find a "brighter" banana?  =)', '2006-04-03 19:16:49.000000', NULL, 1),
(2284612, 314093, 36403, '<td valign="top">Nice shot.  Like the addition of the yellow coveralls.</td>', 'Nice shot.  Like the addition of the yellow coveralls.', '2006-04-03 19:17:10.000000', NULL, 1),
(2284613, 314900, 36403, '<td valign="top">Precious!</td>', 'Precious!', '2006-04-03 19:17:26.000000', NULL, 1),
(2284616, 314041, 36403, '<td valign="top">This looks a lot more "orange" than yellow to me.</td>', 'This looks a lot more "orange" than yellow to me.', '2006-04-03 19:18:26.000000', NULL, 1),
(2284619, 314616, 36403, '<td valign="top">Great skin tone &amp; nice clarity.</td>', 'Great skin tone & nice clarity.', '2006-04-03 19:19:06.000000', NULL, 1),
(2284624, 315318, 36403, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2006-04-03 19:20:10.000000', NULL, 1),
(2284625, 314732, 36403, '<td valign="top">Nice water droplet. Good shot.</td>', 'Nice water droplet. Good shot.', '2006-04-03 19:21:12.000000', NULL, 1),
(2284627, 315684, 36403, '<td valign="top">Cute angle.  Nice job.</td>', 'Cute angle.  Nice job.', '2006-04-03 19:21:27.000000', NULL, 1),
(2284689, 315771, 40797, '<td valign="top">Clever title! I am amazed by the sharpness and clairity of this photo. The details that you were able to capture on this perfectly yellow bumble bee are great. He looks so real. Your color combinations are beautiful too. I like the yellow and pink contrast.</td>', 'Clever title! I am amazed by the sharpness and clairity of this photo. The details that you were able to capture on this perfectly yellow bumble bee are great. He looks so real. Your color combinations are beautiful too. I like the yellow and pink contrast.', '2006-04-03 19:58:43.000000', NULL, 1),
(2284690, 315444, 12448, '<td valign="top">Okay, either this was a deliberate mistake in spelling or a "Oh crap! I can''t believe I forgot the h" mistake.  Either way, it works, I like the pun, tree in one stem and crowd as in by itself. :)  Very nice shot, nice lighting, the glass jar is a good choice, the line of the stem, all well done.  An 8</td>', 'Okay, either this was a deliberate mistake in spelling or a "Oh crap! I can''t believe I forgot the h" mistake.  Either way, it works, I like the pun, tree in one stem and crowd as in by itself. :)  Very nice shot, nice lighting, the glass jar is a good choice, the line of the stem, all well done.  An 8', '2006-04-03 19:59:20.000000', NULL, 1),
(2284694, 315220, 12448, '<td valign="top">I love the shadow and color on this shot but the cropping and set up just seem off.  If you could have centered teh corner more and had the roof lines leading you in one side and out the other side, maybe creating a V in the top part that would really bring a balance to the shot.  As it is, it seems like the whole building is going to fall out the left side of the picture.  The other window frames on the right are also very distracting.  If you ever reshoot this with my suggestions or even recrop with a rotation I would love to see it.  As is a 6</td>', 'I love the shadow and color on this shot but the cropping and set up just seem off.  If you could have centered teh corner more and had the roof lines leading you in one side and out the other side, maybe creating a V in the top part that would really bring a balance to the shot.  As it is, it seems like the whole building is going to fall out the left side of the picture.  The other window frames on the right are also very distracting.  If you ever reshoot this with my suggestions or even recrop with a rotation I would love to see it.  As is a 6', '2006-04-03 20:01:28.000000', NULL, 1),
