INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2292144, 315683, 37103, '<td valign="top">This door is a great subject.  In this particular photo it seems a little out of focus.  I would also maybe approach it from another angle or get higher up so that leafy plant is not blocking so much of the door.</td>', 'This door is a great subject.  In this particular photo it seems a little out of focus.  I would also maybe approach it from another angle or get higher up so that leafy plant is not blocking so much of the door.', '2006-04-06 14:12:53.000000', NULL, 1),
(2292150, 313840, 37103, '<td valign="top">Lovely scene, I''m not sure I like the square crop.</td>', 'Lovely scene, I''m not sure I like the square crop.', '2006-04-06 14:15:24.000000', NULL, 1),
(2292154, 315150, 37103, '<td valign="top">Beautiful still life.  I''m not sure I like the reddish yellow cast on everything.  I think it would be enough just to have yellow flowers.</td>', 'Beautiful still life.  I''m not sure I like the reddish yellow cast on everything.  I think it would be enough just to have yellow flowers.', '2006-04-06 14:16:30.000000', NULL, 1),
(2292156, 314790, 37103, '<td valign="top">This is a great image.  Very creepy and surreal, and I hope we get to hear where this is and how you created this effect.  It works really well for this challenge.</td>', 'This is a great image.  Very creepy and surreal, and I hope we get to hear where this is and how you created this effect.  It works really well for this challenge.', '2006-04-06 14:18:09.000000', NULL, 1),
(2292238, 314043, 50565, '<td valign="top">makes me wanta walk up those!  great shot</td>', 'makes me wanta walk up those!  great shot', '2006-04-06 14:59:26.000000', NULL, 1),
(2292248, 315027, 56736, '<td valign="top">This is a phenominal picture, i like how its so mysterious  yet so good,  keep up the good work!</td>', 'This is a phenominal picture, i like how its so mysterious  yet so good,  keep up the good work!', '2006-04-06 15:11:08.000000', NULL, 1),
(2292260, 313772, 52412, '<td valign="top">beautiful</td>', 'beautiful', '2006-04-06 15:16:41.000000', NULL, 1),
(2292264, 315744, 50641, '<td valign="top">A stunning and natural yellow....  love the geometry.</td>', 'A stunning and natural yellow....  love the geometry.', '2006-04-06 15:18:31.000000', NULL, 1),
(2292266, 315221, 3032, '<td valign="top">Great shot, nice mood (dark background), good colors and good composition.</td>', 'Great shot, nice mood (dark background), good colors and good composition.', '2006-04-06 15:19:23.000000', NULL, 1),
(2292270, 314406, 3032, '<td valign="top">Composition is very centered and head on. Rule of thirds/golden mean and another angle to shoot the boat from would help a lot here. 5</td>', 'Composition is very centered and head on. Rule of thirds/golden mean and another angle to shoot the boat from would help a lot here. 5', '2006-04-06 15:22:42.000000', NULL, 1),
