INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2295718, 314415, 31133, '<td valign="top">Beautiful shades of yellow here. I can''t decide whether I like the tight crop and off-center composition of the cirular part or not... but the most important thing is of course that you got what you wanted. Also like the about of detail captured. Missing a bit of the ''wow'', but can''t define why...</td>', 'Beautiful shades of yellow here. I can''t decide whether I like the tight crop and off-center composition of the cirular part or not... but the most important thing is of course that you got what you wanted. Also like the about of detail captured. Missing a bit of the ''wow'', but can''t define why...', '2006-04-07 18:00:42.000000', NULL, 1),
(2295727, 313708, 31133, '<td valign="top">Flawless placement of the very clean vase and water within the frame, in my opinion. Like the frame too, even though I normally don''t like this kind of frame - fits perfectly here.</td>', 'Flawless placement of the very clean vase and water within the frame, in my opinion. Like the frame too, even though I normally don''t like this kind of frame - fits perfectly here.', '2006-04-07 18:02:48.000000', NULL, 1),
(2295728, 312746, 3032, '<td valign="top">Good portrait, a touch of Librodo.</td>', 'Good portrait, a touch of Librodo.', '2006-04-07 18:02:48.000000', NULL, 1),
(2295731, 314327, 47852, '<td valign="top">Meal?  I wouldn''t eat all of those things at once!  Neat idea and arrangement though! :)</td>', 'Meal?  I wouldn''t eat all of those things at once!  Neat idea and arrangement though! :)', '2006-04-07 18:03:10.000000', NULL, 1),
(2295740, 313224, 3032, '<td valign="top">Nice colors and good horizon profile. Tree adds a bit of interest. Horizon line is too centered imo.</td>', 'Nice colors and good horizon profile. Tree adds a bit of interest. Horizon line is too centered imo.', '2006-04-07 18:05:52.000000', NULL, 1),
(2295751, 315286, 3032, '<td valign="top">Great composition, light and colors. 8</td>', 'Great composition, light and colors. 8', '2006-04-07 18:08:21.000000', NULL, 1),
(2295759, 314112, 3032, '<td valign="top">Great composition with that shadow stair. The poster, fence and traffic sign are well balanced within that. 10</td>', 'Great composition with that shadow stair. The poster, fence and traffic sign are well balanced within that. 10', '2006-04-07 18:09:44.000000', NULL, 1),
(2295761, 315810, 3032, '<td valign="top">Stands out well.</td>', 'Stands out well.', '2006-04-07 18:10:11.000000', NULL, 1),
(2295764, 313446, 3032, '<td valign="top">Interesting portrait, contrast in the yellow is a bit flat and I don''t understand the girly dress. 7</td>', 'Interesting portrait, contrast in the yellow is a bit flat and I don''t understand the girly dress. 7', '2006-04-07 18:10:57.000000', NULL, 1),
(2295766, 312592, 3032, '<td valign="top">Sweet pastels, nice composition. Shallow dof works for me. 8</td>', 'Sweet pastels, nice composition. Shallow dof works for me. 8', '2006-04-07 18:11:39.000000', NULL, 1),
(2295767, 315642, 3032, '<td valign="top">Great composition and balance between light and dark. Nice.</td>', 'Great composition and balance between light and dark. Nice.', '2006-04-07 18:12:07.000000', NULL, 1),
(2295772, 313559, 31133, '<td valign="top">Beautiful flower, but the saturation is a bit high for my taste, or maybe it''s just that the loss of detail in the bottom petals is making it look really super saturated. I like the background.</td>', 'Beautiful flower, but the saturation is a bit high for my taste, or maybe it''s just that the loss of detail in the bottom petals is making it look really super saturated. I like the background.', '2006-04-07 18:13:39.000000', NULL, 1),
(2295777, 313084, 31133, '<td valign="top">These are extraordinarly cute little peeps and nice comp. My only criticism is the focus - I think a tripod would''ve contributed a lot here.</td>', 'These are extraordinarly cute little peeps and nice comp. My only criticism is the focus - I think a tripod would''ve contributed a lot here.', '2006-04-07 18:14:46.000000', NULL, 1),
(2295780, 315786, 31133, '<td valign="top">Nice job, even if I''m not a selective desat fan. I like the lettering on the bus and the fact that it''s sooo old there aren''t even wheels.</td>', 'Nice job, even if I''m not a selective desat fan. I like the lettering on the bus and the fact that it''s sooo old there aren''t even wheels.', '2006-04-07 18:16:10.000000', NULL, 1),
(2295790, 315733, 3032, '<td valign="top">Great scene, good eye.</td>', 'Great scene, good eye.', '2006-04-07 18:20:14.000000', NULL, 1),
(2295791, 315803, 31133, '<td valign="top">The detail here is amazing. Not a single mistake that I can see. Love that you have the red ladybug to makimize the color experience!</td>', 'The detail here is amazing. Not a single mistake that I can see. Love that you have the red ladybug to makimize the color experience!', '2006-04-07 18:20:33.000000', NULL, 1),
(2295796, 313925, 31133, '<td valign="top">Nice job with focus and color. Would like to see a slightly less tight crop, to give the flowers some breathing room.</td>', 'Nice job with focus and color. Would like to see a slightly less tight crop, to give the flowers some breathing room.', '2006-04-07 18:22:40.000000', NULL, 1),
(2295799, 314364, 31133, '<td valign="top">Clever compostion with the daffodils in the foreground! A little more pizazz in the sky would balance the shot nicely, in my opinion.</td>', 'Clever compostion with the daffodils in the foreground! A little more pizazz in the sky would balance the shot nicely, in my opinion.', '2006-04-07 18:23:55.000000', NULL, 1),
